import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0001: Why Rust","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0001-why-rust.md","filePath":"adr/ADR-0001-why-rust.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0001-why-rust.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0001-why-rust" tabindex="-1">ADR-0001: Why Rust <a class="header-anchor" href="#adr-0001-why-rust" aria-label="Permalink to “ADR-0001: Why Rust”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: docs/guide/overview.md, workspace.md</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>Custos is a persistent local self-healing engine: long-running, latency-sensitive, must be cross-platform (Linux/Windows first), single-binary deployment, with strict state machines in the domain model (recovery runs, health transitions, budgets, mutexes). The language choice determines memory safety, deployment shape, and long-term maintenance cost.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Rust as the only implementation language: domain models type-encoded (<code>HealthStatus</code> seven states, <code>RecoveryRunStatus</code> state machine, strongly-typed IDs), workspace layered by crate (model/engine/probe/notify/store/config/cli), async only inside the store (sync facade + current-thread runtime), TLS via rustls for pure-Rust cross-compilation.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>Go</strong>: GC pauses and higher persistent memory footprint; error handling by convention (err != nil) with no compile-time constraint; cross-compilation to a single binary works but state-machine correctness relies on humans.</li><li><strong>C/C++</strong>: Memory safety is unacceptable — a self-healing engine holds system-level privileges; UAF/overflow is privilege escalation.</li><li><strong>Python/Scripts</strong>: Performance and deployment (interpreter, dependency tree) unsuitable for a persistent engine; weak type constraints.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: predictable latency without GC; <code>enum + match</code> exhaustiveness makes missing state-machine branches a compile-time error; mature ecosystem (rustls/sqlx/lettre/ureq) aligns with the &quot;core uses mature crates&quot; ruling; single binary, mingw cross-compilation verified. Cons: longer compile times; slower iteration than scripting languages; some ecosystem complexity (PyO3 outbound bindings).</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li>The 11-crate workspace layering is carried by Rust&#39;s module system (one-way dependencies).</li><li>All &quot;core uses mature crates, plugin-side is lightweight&quot; rulings build on this.</li><li>rust-toolchain.toml must declare the stable channel (todo.md engineering cleanup).</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};